  rangar: [[135, "Mästerdetektiv"], [100, "Skarpsynt spårhund"], [60, "Lovande nos"], [25, "Glasögonlös amatör"], [0, "Kaffeautomat i trenchcoat"]],

  ledtradar: [
    { om: { inteFlagga: "uppdrag" }, text: "Någon har stuckit in något under dörren. Läs det." },
    { om: { inteBar: "kort", inteFlagga: "ladaLoss" }, text: "Ditt tunnelbanekort ligger i skrivbordslådan, men lådan kärvar. Den behöver bändas upp med något platt. Titta på skrivbordet." },
    { om: { inteBar: "kort", objektPa: ["kort", "lada"] }, text: "Lådan är öppen. Ta det som ligger i den." },
    { om: { inteFlagga: "inslappt" }, text: "Telegrammet sa vart du ska och vem du ska visa det för. Åk till Boulevarden." },
    { om: { inteFlagga: "klient" }, text: "Lola väntar i logen, bakom scenen på Blå Ostronet." },
    { om: { inteFlagga: "papegoja", inteBar: "rock" }, text: "Lola sa att Caruso bara pratar i sömnen, när det är mörkt i buren. Har du något stort att täcka en bur med? Kanske hänger det på kontoret." },
    { om: { inteFlagga: "papegoja" }, text: "Använd något stort och mörkt på buren, så tror Caruso att det är natt." },
    { om: { inteFlagga: "klocka" }, text: "Vilken klocka slår tretton? Fråga folk på Boulevarden. Någon som har med klockor att göra vet säkert." },
    { om: { inteFlagga: "adress" }, text: "Tre trappor upp, i huset med klockan som slår tretton. Vem bor där? Titta på porttelefonen och ring på." },
    { om: { inteFlagga: ["stegeUr", "pant"], inteBar: "paraply" }, text: "Porten är låst, men gränden bakom huset har brandstegar. Stegen hänger för högt; du behöver något med en krok. Pantbanken säljer sådant, men du har inga pengar. Har du något värdelöst som andra skulle skratta åt?" },
    { om: { inteFlagga: "stegeUr", inteBar: "paraply" }, text: "Köp paraplyet med kroken i pantbanken." },
    { om: { inteFlagga: "stegeUr" }, text: "Använd paraplyet på urmakarens brandstege i gränden." },
    { om: { inteFlagga: ["ljus", "batterierKopt"], inteBar: "batterier" }, text: "Det är mörkt i lägenheten. Ficklampan i skrivbordslådan behöver nya batterier, och pantbanken har batterier." },
    { om: { inteFlagga: "ljus" }, text: "Använd batterierna på ficklampan." },
    { om: { inteFlagga: "brandtrappa" }, text: "Klättra upp till tredje våningen på urmakarens brandstege." },
    { om: { inteFlagga: "inne" }, text: "Gå in genom fönstret med ficklampan tänd." },
    { om: { inteBar: "noter" }, text: "Noterna ligger någonstans i lägenheten. Titta i det som går att öppna." },
    { om: { inteFlagga: "bevis", inteBar: "brev_f" }, text: "Ta med dig brevet från lägenheten. Det avslöjar vem tjuven är." },
    { om: { inteFlagga: "bevis" }, text: "Visa brevet för den som skrev det. Han sitter vid flygeln på Blå Ostronet." },
    { text: "Ge noterna till Lola i logen." },
  ],

